import { Card, Cards, getRank, Pile, playableCards, Player } from "./lib";

export function bot(pile: Pile, player: Player): Card | undefined {
  const visibleHand = [
    player.hand,
    player.offHand.faceUp.filter((card) => card !== undefined) as Cards,
  ].find((hand) => hand.length);
  if (visibleHand !== undefined) {
    const playable = playableCards(pile);
    const choice = visibleHand.filter((card) =>
      playable.some((playableCard) => getRank(playableCard) === getRank(card))
    );
    if (!choice.length) return;
    return choice[Math.floor(Math.random() * choice.length)];
  }
  return player.offHand.faceDown.find((card) => card !== undefined);
}

function topCard(pile: Readonly<Pile>): Card | undefined {
  const top = pile.at(-1);
  if (top === undefined) return;
  if (getRank(top) === Rank.Num8) return topCard(pile.slice(0, -1));
  return top;
}

export function canPlay(card: Readonly<Card>, pile: Readonly<Pile>): boolean {
  if ([Rank.Num2, Rank.Num8].includes(getRank(card))) return true;
  const top = topCard(pile);
  if (top === undefined) return true;
  if (getRank(top) === Rank.Num7) return getRank(card) <= getRank(top);
  return getRank(card) >= getRank(top);
}

export function dealHand(rng: Rng, deck: readonly SideCard[]): SideCard[] {
  const shuffled = [...deck];
  rng.shuffle(shuffled);
  const hand: SideCard[] = [];
  const seen = new Set<string>();
  for (const c of shuffled) {
    if (hand.length >= HAND_SIZE) break;
    if (seen.has(c.code)) continue;
    seen.add(c.code);
    hand.push(c);
  }
  for (let i = 0; hand.length < HAND_SIZE && shuffled.length > 0; i++) {
    hand.push(shuffled[i % shuffled.length]);
  }
  return hand;
}

export interface CampaignTier {
  name: string;
  codes: readonly string[];
}

export const CAMPAIGN_TIERS: readonly CampaignTier[] = [
  { name: 'VeryEasy', codes: ['+3', '-3', '+4', '-4', '+5', '-5', '+5', '-3', '+4', '-5'] },
  { name: 'Easy', codes: ['+1', '+2', '+3', '+4', '+5', '-6', '-4', '-3', '-2', '-1'] },
  { name: 'Average', codes: ['±1', '±2', '+3', '+4', '+5', '+6', '±5', '-6', '±4', '±6'] },
  { name: 'Hard', codes: ['±3', '±4', '±5', '±6', '±6', '+6', '-6', '±4', '+5', '±5'] },
  { name: 'VeryHard', codes: ['±6', '±5', '±6', '±4', '±5', '±6', '±3', '±6', '±5', '±4'] },
];

export const CAMPAIGN_LENGTH = CAMPAIGN_TIERS.length;

export function aiDeck(tierIndex: number): SideCard[] {
  const tier = CAMPAIGN_TIERS[tierIndex];
  if (!tier) throw new Error(`no campaign tier ${tierIndex}`);
  return tier.codes.map(card);
}

findClosestEnemy(unit: Unit): Unit | null {
    const enemyCells = this.board.getUnits()
        .filter(u => u.player !== this)
        .map(u => u.cell)
        .filter(c => !!c) as Cell[];

    const closestCell = this.findClosestCell(unit, enemyCells);
    if (closestCell?.unit) {
        return closestCell.unit;
    }
    return null;
}

findValidMoveCells(unit: Unit): Cell[] {
    // pick a random valid move
    let range: PathNodeComponent[] = [];
    if (unit.cell) {
        // find empty or enemy occupied cells
        range = this.board.pathFinder.getRange(unit.cell.pathNode, this.mask, unit.unitConfig.movement).filter(node => {
            const cell = node.owner as Cell;
            return cell.unit?.player !== this;
        });
    }
    return range.map(node => node.owner as Cell);
}

findClosestCell(unit: Unit, cells: Cell[]) {
    let closest = cells[0];
    if (closest) {
        let distance = Infinity;
        for (let cell of cells) {
            const cellDistance = cell.pos.squareDistance(unit.cell?.pos ?? ex.vec(0, 0));
            if (cellDistance < distance) {
                closest = cell;
                distance = cellDistance;
            }
        }
        return closest;
    }
    return null;
}

findAttackableTargets(unit: Unit): Cell[] {
    this.selectionManger.selectUnit(unit, "attack");
    const attackRange = this.selectionManger.findAttackRange(unit);
    return attackRange.filter(node => {
        if (node.owner) {
            const cell = node.owner as Cell;
            if (cell.unit) {
                return cell.unit.player !== this;
            }
        }
        return false;
    }).map(node => node.owner as Cell);
}

export function gridToScreenSpace(gridPos: GridCoordinates, mapSize: Size2D): ScreenCoordinates {
  const mapWidth = mapSize.width;

  const tileWidth = constants.tileSize.width;
  const tileHeight = constants.tileSize.height;

  const halfWidth = tileWidth / 2;
  const halfHeight = tileHeight / 2;

  const x = (gridPos.x - gridPos.y) * halfWidth + (mapWidth / 2 - 0.5) * tileWidth;
  const y = (gridPos.x + gridPos.y) * halfHeight;

  return { x, y };
}

export function screenToGridSpace(screenPos: GridCoordinates, mapSize: Size2D): GridCoordinates {
  const mapWidth = mapSize.width;
  const mapHeight = mapSize.height;

  const tileWidth = constants.tileSize.width;
  const tileHeight = constants.tileSize.height;

  const halfWidth = tileWidth / 2;
  const halfHeight = tileHeight / 2;

  const x = 0.5 * ((screenPos.x - (mapWidth / 2 - 0.5) * tileWidth) / halfWidth + screenPos.y / halfHeight);
  const y = 0.5 * (-(screenPos.x - (mapHeight / 2 - 0.5) * tileWidth) / halfWidth + screenPos.y / halfHeight);

  return { x, y };
}

update(delta) {

    if (this.aimingAt && this.aimingAt.isDead()) {
        this.aimingAt = undefined
    }

    this.coolDown -= 1
    const nearest = this.scene.getNearestKnight({x: this.sprite.x, y: this.sprite.y})

    if (nearest && this.aimingAt !== nearest) {
        this.aimingAt = nearest
    }

    if (this.aimingAt) {
        const {x, y} = this.aimingAt.getXY()
        const {velX, velY} = this.aimingAt.getVelXY()
        const dist = (new Vector2(x - this.sprite.x, this.sprite.y - y)).length()
        const fromGun = new Vector2(x + velX * delta * dist / 500 - this.sprite.x, this.sprite.y - y - velY * delta * dist / 500)
        const fromGunNormalized = fromGun.normalize()
        const angle = Math.asin(fromGunNormalized.y) * 180 / Math.PI
        const translatedAngle = fromGunNormalized.x > 0
            ? 90 - angle
            : angle - 90
        const angleDiff = this.sprite.angle - translatedAngle
        if (Math.abs(angleDiff) > 10) {
            const spriteAngle360 = this.sprite.angle < 0 ? 360 + this.sprite.angle : this.sprite.angle
            const aimingAtAngle360 = translatedAngle < 0 ? 360 + translatedAngle : translatedAngle
            const dir = aimingAtAngle360 > spriteAngle360
                ? (aimingAtAngle360 - spriteAngle360 <= 180 ? 1 : -1)
                : (spriteAngle360 - aimingAtAngle360 <= 180 ? -1 : 1)
            this.sprite.setAngularVelocity(dir / 5)
        } else {
            // TODO: Implement range
            if (this.coolDown <= 0) {
                const spriteAngle360 = this.sprite.angle < 0 ? 360 + this.sprite.angle : this.sprite.angle
                const {x, y} = {
                    x: Math.cos((450 - spriteAngle360) % 360 / 180 * Math.PI),
                    y: Math.sin((450 - spriteAngle360) % 360 / 180 * Math.PI)
                }
                this.generateBullets(x, y)
                this.coolDown = this.gunParams.coolDown
            }
            this.sprite.setAngularVelocity(0)
        }
    } else {
        this.sprite.setAngularVelocity(0)
    }
}

export type Card = number;
export const SUITE_BIN_WIDTH = 2;

export function createCard(suite: Readonly<Suite>, rank: Readonly<Rank>): Card {
  return (rank << SUITE_BIN_WIDTH) | suite;
}

function _1s(n: number): number {
  return (1 << n) - 1;
}

export function getSuite(card: Readonly<Card>): Suite {
  return card & _1s(SUITE_BIN_WIDTH);
}

export const RANK_BIN_WIDTH = 4;

export function getRank(card: Readonly<Card>): Rank {
  return (card >> SUITE_BIN_WIDTH) & _1s(RANK_BIN_WIDTH);
}

function createRanks(): Rank[] {
  return [
    Rank.Ace,
    Rank.Num2,
    Rank.Num3,
    Rank.Num4,
    Rank.Num5,
    Rank.Num6,
    Rank.Num7,
    Rank.Num8,
    Rank.Num9,
    Rank.Num10,
    Rank.Jack,
    Rank.Queen,
    Rank.King,
  ];
}

function createSuites(): Suite[] {
  return [Suite.Clubs, Suite.Diamonds, Suite.Hearts, Suite.Spades];
}

export type Cards = Card[];
export type Deck = Cards;
export type Pile = Cards;

export function createDeck(): Deck {
  return createSuites().flatMap((suite) =>
    createRanks().map((rank) => createCard(suite, rank))
  );
}

export function isPileBurnable(pile: Readonly<Pile>): boolean {
  const topCard = pile.at(-1);
  if (topCard === undefined) return false;
  const isTopCard10 = getRank(topCard) === Rank.Num10;
  const areTop4CardsSameRank =
    pile.length >= 4 &&
    pile.slice(-4).every((card) => getRank(card) === getRank(topCard));
  return isTopCard10 || areTop4CardsSameRank;
}

const STARTING_HAND_SIZE = 6;
const STARTING_FACEDOWN_SIZE = 3;

export function dealCards(deck: Readonly<Deck>): [Deck, Player] {
  const deckCopy = deck.slice();
  const player = makePlayer();
  player.hand = deckCopy.splice(-STARTING_HAND_SIZE);
  player.offHand.faceDown = deckCopy.splice(
    -STARTING_FACEDOWN_SIZE
  ) as OffHandCards;
  return [deckCopy, player];
}

export function dealCardsFor(
  playerCount: number,
  deck: Readonly<Deck>
): [Deck, Player[]] {
  let newDeck = deck.slice();
  const players = [];
  for (let i = 0; i < playerCount; i++) {
    let player;
    [newDeck, player] = dealCards(newDeck);
    players.push(player);
  }
  return [newDeck!, players];
}

export function shuffle<T>(array: T[]): T[] {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

export function applyResult(progress: CampaignProgress, won: boolean, difficulty: Difficulty): CampaignProgress {
  if (won) {
    const tier = Math.min(progress.tier + 1, CAMPAIGN_LENGTH);
    return { tier, everCompleted: progress.everCompleted || tier >= CAMPAIGN_LENGTH };
  }
  if (difficulty === 'hardcore') {
    return { tier: 0, everCompleted: progress.everCompleted };
  }
  return progress;
}

export const restarted = (progress: CampaignProgress): CampaignProgress => ({ tier: 0, everCompleted: progress.everCompleted });

const key = (difficulty: Difficulty) => `pz-campaign-${difficulty}`;

export function loadProgress(difficulty: Difficulty): CampaignProgress {
  try {
    const raw = localStorage.getItem(key(difficulty));
    if (!raw) return FRESH;
    const p = JSON.parse(raw) as Partial<CampaignProgress>;
    const tier = typeof p.tier === 'number' ? Math.max(0, Math.min(p.tier, CAMPAIGN_LENGTH)) : 0;
    return { tier, everCompleted: !!p.everCompleted };
  } catch {
    return FRESH;
  }
}

export function saveProgress(difficulty: Difficulty, progress: CampaignProgress): void {
  try {
    localStorage.setItem(key(difficulty), JSON.stringify(progress));
  } catch {
  }
}

export interface Rng {

  randint(a: number, b: number): number;

  shuffle<T>(list: T[]): void;

  sample<T>(list: readonly T[], k: number): T[];
}


export class SeededRng implements Rng {
  private state: number;

  constructor(seed = Date.now() >>> 0) {
    this.state = seed >>> 0;
  }

  private next(): number {

    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  randint(a: number, b: number): number {
    return a + Math.floor(this.next() * (b - a + 1));
  }

  shuffle<T>(list: T[]): void {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
  }

  sample<T>(list: readonly T[], k: number): T[] {
    const pool = [...list];
    this.shuffle(pool);
    return pool.slice(0, k);
  }
}

export type BuiltInCardPool = 'classic' | 'flip' | 'mix';
export type CardPool = BuiltInCardPool | 'builder';
export type Difficulty = 'easy' | 'normal' | 'hard' | 'hardcore';

const byFamily = (families: string[]): SideCard[] => FULL_COLLECTION.filter((c) => families.includes(c.family));

export const POOLS: Record<BuiltInCardPool, readonly SideCard[]> = {
  classic: byFamily(['plus', 'minus']),
  flip: byFamily(['flip']),
  mix: byFamily(['plus', 'minus', 'flip']),
};

export const DIFFICULTY_POOL: Record<Difficulty, BuiltInCardPool> = {
  easy: 'flip',
  normal: 'mix',
  hard: 'classic',
  hardcore: 'classic',
};

export function deckFromPool(rng: Rng, pool: BuiltInCardPool): SideCard[] {
  const src = POOLS[pool];
  return Array.from({ length: SIDE_DECK_SIZE }, () => src[rng.randint(0, src.length - 1)]);
}

export function playerDeck(rng: Rng, difficulty: Difficulty): SideCard[] {
  return deckFromPool(rng, DIFFICULTY_POOL[difficulty]);
}

export function chooseBotAction(game: PazaakGame, player: number): Action {
  const me = game.players[player];
  const opp = game.players[1 - player];
  const total = me.total;

  const [bestPlay, bestTotal] = bestHandPlay(game, player);

  if (total > WINNING_TOTAL) {

    if (bestPlay !== null && bestTotal <= WINNING_TOTAL) {
      return bestPlay;
    }
    return Stand();
  }

  if (!me.playedThisTurn && bestPlay !== null && bestTotal === WINNING_TOTAL) {
    return bestPlay;
  }

  if (total === WINNING_TOTAL) {
    return Stand();
  }


  if (opp.standing && total >= opp.total && total <= WINNING_TOTAL) {
    return Stand();
  }

  if (total >= STAND_THRESHOLD && !(opp.standing && opp.total > total)) {
    return Stand();
  }

  return EndTurn();
}

